declarations.EC:
public class EC {
 public Integer calls=0;
 public String value;
 public EC child;
 public Boolean mark(Boolean result){calls++; return result;}
 public Integer number(Integer result){calls++; return result;}
 public String text(String result){calls++; return result;}
 public EC link(){calls++; return child;}
}

declarations.ECIterator:
public class ECIterator implements Iterator<Integer> {
 public Integer pos=0;
 public Integer stopAt;
 public ECIterator(Integer n){stopAt=n;}
 public Boolean hasNext(){return pos<stopAt;}
 public Integer next(){return pos++;}
}

declarations.ECIterable:
public class ECIterable implements Iterable<Integer> {
 public Integer stopAt;
 public ECIterable(Integer n){stopAt=n;}
 public Iterator<Integer> iterator(){return new ECIterator(stopAt);}
}

declarations.ECKey:
public class ECKey {
 public Integer value;
 public ECKey(Integer n){value=n;}
 public Boolean equals(Object other){return other instanceof ECKey && value==((ECKey)other).value;}
 public Integer hashCode(){return value==null ? 0 : value;}
}
